/// </summary>
[ExtensionOf(formStr(SalesTable))]
final class METSalesTableFrm_Extension
{

}

Method.Source:
/// <summary>
/// JumpRef method for field METPalletRounding_PalletRoundingPolicyLineRefRecId
/// to filter down pallet rounding policies with the one applied to the sales order line. - CB223_PalletRounding
/// </summary>
/// <param name = "_formControl">METPalletRounding_PalletRoundingPolicyLineRefRecId control in form SalesTable</param>
public void METPalletRoundingPolicyLineRefRecIdJumpRef(FormInt64Control _formControl)
{
    Args args = new Args();
    MenuFunction menuFunction;

    args.record(METPalletRoundingPolicyLine::findRecId(any2Int64(_formControl.value())));

    menuFunction = new MenuFunction(menuitemdisplaystr(METPalletRoundingPolicySetup), MenuItemType::Display);
    menuFunction.run(args);

}

/// <summary>
/// Performs additional actions when the sales order is created.
/// </summary>
protected void salesTableCreated()
{
    next salesTableCreated();

    METSalesTable.data(SysExtensionSerializerExtensionMap::findByBase(
        METSalesTable.TableId,
        SalesTable.RecId,
        true));

    METSalesTable_ds.rereadReferenceDataSources();
}
